export const postsSlides: Record<string, PostSlide[]> = {
  "cron-jobs-in-five-minutes":[
    {num:"", label:"tips", title:"Stop Running Things Manually", subtitle:"", body:"If you keep opening the terminal to run the same command on the same schedule, you are the cron job. It's time to fix that.", theme:"black"},
    {num:"02", label:"The Pain", title:"You Are Already The Cron Job", body:"Every morning. Every Friday. Every deploy. You SSH in, run the thing, close the window. Until you forget once, and now there's an incident.", bullets:["Daily backup you keep meaning to script.","Cleanup that fails when you go on holiday.","Manual reports that should email themselves."], theme:"black"},
    {num:"03", label:"The Idea", title:"It's Just A Schedule + Command", body:"A cron job is one line. Five fields that say when, followed by the command. The whole thing is shorter than this body text.", code:"# Run every day at 6am\n0 6 * * *  /usr/local/bin/backup.sh\n\n# Run every Monday at 9am\n0 9 * * 1  npm run weekly-report", theme:"black"},
    {num:"04", label:"The Syntax", title:"Five Asterisks, Read Left To Right", body:"Minute, hour, day-of-month, month, day-of-week. Use a number, a list, or a star for any. That's the whole language.", code:"*  *  *  *  *  command\n|  |  |  |  |\n|  |  |  |  +-- day of week (0-6, Sun=0)\n|  |  |  +----- month (1-12)\n|  |  +-------- day of month (1-31)\n|  +----------- hour (0-23)\n+-------------- minute (0-59)", theme:"black"},
    {num:"05", label:"Where It Lives", title:"Pick The Wrapper That Fits", body:"The five asterisks haven't changed in decades. What changes is where you put them. Modern platforms hide the server entirely.", bullets:["Linux: crontab -e on your VPS.","Vercel: vercel.json `crons` block.","GitHub Actions: schedule trigger on workflow.","App-level: node-cron, BullMQ, Sidekiq."], theme:"black"},
    {num:"06", label:"Gotchas", title:"Two Things That Will Bite", body:"Almost everyone trips on the same two issues the first time. Knowing them upfront saves an hour of confusion.", bullets:["Timezone: most cron is UTC by default.","No retries: if it fails, it just fails.","Log everything. Cron runs silently."], theme:"black"},
    {num:"07", label:"Closing", title:"Five Asterisks. That's The Whole Wall.", body:"The syntax looked scary, so you ran things by hand. Five minutes of learning it pays back every week for the rest of your career.", bullets:["If you do it twice, automate it.","Start with one daily job. Build from there."], theme:"black"},
  ],
  "save-claude-tokens-rtk-caveman":[
    {num:"", label:"tips", title:"Stop Burning Claude Credits", body:"Every git status, every grep, every paragraph of polite prose costs tokens. Two tools cut a normal session's bill by 90%. Setup takes ten minutes.", theme:"white"},
    {num:"02", label:"Where Tokens Go", title:"It's Not The Code", body:"Look at any long session and the cost lives in two places. Bash output piped back to the model, and the model's own verbose explanations.", bullets:["git status returns 200 lines. You needed 5.","Replies open with 'Great question!' every time.","Build logs eat half a context window."], theme:"white"},
    {num:"03", label:"Tool 1", title:"RTK Filters Bash Before It Speaks", body:"Rust Token Killer is a CLI proxy. It runs your commands, strips noise, and hands the model only the parts that matter.", code:"# Install once\nbrew install rtk\n\n# Verify\nrtk --version\nrtk gain   # see lifetime savings", theme:"white"},
    {num:"04", label:"Tool 2", title:"Caveman Compresses Replies", body:"Caveman is a skill that tells Claude to drop filler. Same answers, 75% fewer words.", code:"# Turn on\n/caveman\n\n# Or save forever in\n~/.claude/CLAUDE.md\n\n# Levels: lite, full, ultra", theme:"white"},
    {num:"05", label:"Combined Effect", title:"Roughly 90% Off", body:"RTK cuts the input side. Caveman cuts the output side. Together they drop a typical session from 200k tokens to under 25k.", bullets:["RTK: 60 to 90% off bash output.","Caveman: ~75% off model prose.","Compound: 90%+ off the whole session."], theme:"white"},
    {num:"06", label:"Gotchas", title:"Two Things To Know", body:"RTK is opinionated about find syntax and a few other commands. Caveman keeps tech accuracy but can read terse to newcomers.", bullets:["RTK rejects compound find predicates.","Caveman ultra reads blunt. Use lite for shared chats.","Both have a proxy escape hatch when needed."], theme:"white"},
    {num:"07", label:"Closing", title:"Ten Minutes, Months Of Credits", body:"Install both tonight. Tomorrow's first session uses 10% of what last week's did.", bullets:["RTK = brew install. Hook handles the rest.","Caveman = one line in CLAUDE.md."], theme:"white"},
  ],
  "css-container-queries":[
    {num:"", label:"css", title:"Components That Scale", body:"Stop using media queries when you need a component to look right in a sidebar AND a hero. There's a one-line fix, and it changes how you write CSS.", theme:"white"},
    {num:"02", label:"The Problem", title:"Media Queries Miss The Point", body:"The same card might live in a 250px sidebar and a 900px hero. Media queries don't know which.", bullets:["Components live in many widths.","Viewport size is the wrong signal.","Breakpoint guesswork never ends."], theme:"white"},
    {num:"03", label:"The Tool", title:"Ask Your Parent's Size", body:"Declare a container, and its descendants can finally ask: how big is my parent right now?", code:".card {\n  /* I am a container.\n     Track my width. */\n  container-type: inline-size;\n}", theme:"white"},
    {num:"04", label:"The Units", title:"1cqi = 1% Of Container", body:"Like vw and vh, but anchored to the container instead of the viewport. Sizes scale linearly with whatever box you're inside.", code:".card .title {\n  font-size: 4cqi;   /* 4% of card width */\n  padding: 2cqi;\n}\n/* card 400px wide -> 16px\n   card 800px wide -> 32px */", theme:"white"},
    {num:"05", label:"The Pattern", title:"One Knob, Whole Composition", body:"Set font-size at the root in cqi. Use em for everything else. The component now scales like an SVG, except it's just HTML and CSS.", code:".card .inner {\n  font-size: 4cqi;\n}\n.title  { font-size: 2.5em; }\n.body   { font-size: 0.9em; }\n.avatar { height: 1.4em; }\n.grid   { gap: 1.5em; }", theme:"white"},
    {num:"06", label:"Gotcha", title:"It Can't Query Itself", body:"The first time you try this, it breaks. cqi skips past the element it's declared on. You need two: one declares the container, one consumes it.", code:"/* WRONG. cqi resolves\n   against the viewport */\n.card {\n  container-type: inline-size;\n  font-size: 4cqi;\n}\n\n/* RIGHT. Split into two */\n.card  { container-type: inline-size; }\n.inner { font-size: 4cqi; }", theme:"white"},
    {num:"07", label:"Closing", title:"Use For Reusable UI", body:"Cards, badges, slide previews. Anything that travels between widths. Skip it for body copy.", bullets:["Great for: components, widgets, tiles.","Skip for: articles, long-form prose.","Hybrid: pair cqi with clamp()."], theme:"white"},
  ],
  "ai-coding-agent-operating-model":[
    {num:"", label:"coding", title:"Your AI Is Not Autocomplete", body:"It's a fast junior who needs direction. Get it right and you ship faster. Get it wrong and you ship confident garbage.", theme:"black"},
    {num:"02", label:"The Shift", title:"It Reads, Runs, Recovers", body:"Today's agents touch your filesystem, run your tests, and fix their own mistakes.", bullets:["Edits across many files in one pass.","Reads errors, retries, self-corrects.","Still hallucinates without context."], theme:"black"},
    {num:"03", label:"Where It Shines", title:"Boring Work, Verifiable Wins", body:"AI is happiest with scoped tasks where you can tell if it's right in under 60 seconds.", bullets:["UI from an approved design spec.","Refactors with tests as a safety net.","Docs, summaries, repetitive cleanup."], theme:"black"},
    {num:"04", label:"Where It Breaks", title:"It's Not A Senior Engineer", body:"Hand it vague intent and you'll get confident wrongness.", bullets:["Fails when the goal isn't clear.","Wants one task, not your whole sprint.","You're still the architect. Always."], theme:"black"},
    {num:"05", label:"What Works", title:"Tight Loops Beat Big Prompts", body:"Prompt, run, check, adjust. Fast. The agent gets useful exactly when feedback is cheap and quick.", bullets:["Feed it repo, files, constraints.","Run tests after every small change.","Many small loops beat one mega-prompt."], theme:"black"},
    {num:"06", label:"The Mindset", title:"Design The System, Not The Code", body:"Great teams don't toss prompts and pray. They build an environment where good output is the default.", bullets:["Clear instructions = better first drafts.","Review habits keep the speed honest."], theme:"black"},
  ],
  "mobile-frameworks-2026":[
    {num:"", label:"tips", title:"Pick Your Mobile Stack", body:"There's no universal winner. Only a winner for your team, your timeline, and the product you're actually building.", theme:"white"},
    {num:"02", label:"Decision Inputs", title:"Start With Constraints", body:"Most framework debates skip the only question that matters. What does YOUR team need to ship? By when? With whom?", bullets:["Timeline and hiring runway.","Performance and native depth needs.","How much platform-specific work?"], theme:"white"},
    {num:"03", label:"React Native", title:"Best For Web-Heavy Teams", body:"If you already ship React on the web, RN gives you a mobile app without hiring new humans.", bullets:["Real skill transfer from web to mobile.","Mature ecosystem, huge community.","Fast default for product-led teams."], theme:"white"},
    {num:"04", label:"Flutter", title:"Best For Pixel Control", body:"Flutter shines when the UI IS the product. Same render on every device. But yes, you'll learn Dart.", bullets:["Identical visuals across devices.","Strong for design-led apps.","Confirm Dart works for your team."], theme:"white"},
    {num:"05", label:"Native Paths", title:"Best For Deep Platform Work", body:"When the product IS the integration (watches, AR, top-100 apps), native wins.", bullets:["Built for platform-first roadmaps.","Higher specialization cost upfront.","Worth it when native is the moat."], theme:"white"},
    {num:"06", label:"Closing", title:"Fit Wins, Hype Loses", body:"The loudest framework wins on Twitter. The right framework ships your product.", bullets:["Business goals first.","Team capability second.","Framework preference last."], theme:"white"},
  ],
  "rubiks-cube-beginner-flow":[
    {num:"", label:"hobby", title:"You Can Solve The Cube", body:"Not in 20 seconds. But in a weekend. The trick is to stop trusting your instincts and start trusting layers.", theme:"black"},
    {num:"02", label:"Step 1", title:"Start With The Cross", body:"Forget the rest of the cube exists. Just line up four white edges with the matching centers.", bullets:["Ignore the corners. Completely.","Accuracy beats speed every time."], theme:"black"},
    {num:"03", label:"Step 2", title:"Build The First Layer", body:"Now slot in the four white corners, one at a time. You'll mess up. That's literally how your hands learn.", bullets:["Check side colors before locking in.","Undoing mistakes is the work."], theme:"black"},
    {num:"04", label:"Step 3", title:"Slip In The Middle Edges", body:"Two algorithms, mirror images of each other. Don't memorize them. Feel the rhythm. Up, around, down.", bullets:["One edge at a time. Slow it down.","Repeat until it stops feeling weird."], theme:"black"},
    {num:"05", label:"Step 4", title:"Crack The Last Layer", body:"This is where everyone gets stuck. The secret: recognize the pattern first, then trust the sequence.", bullets:["Orient the top face before permuting.","Trust the algorithm. It works."], theme:"black"},
    {num:"06", label:"Closing", title:"Habits Beat Panic-Twisting", body:"Beginners who slow down learn fastest. The cube rewards calm hands and clean patterns way more than speed.", bullets:["Same sequence every session.","Recognize patterns; don't memorize."], theme:"black"},
  ],
  "kmp-leverage-post":[
    {num:"", label:"mobile", title:"KMP: Leverage, Not Replacement", body:"Datang ingin tahu KMP. Pulang kepikiran: ternyata positioning-nya sangat berbeda dari yang saya bayangkan.", theme:"white"},
    {num:"02", label:"Dua Pertanyaan", title:"Speed Yang Sesungguhnya", body:"Di sesi Iqbal Fauzi, KMP didemo langsung di device low-end. Bukan slide. Bukan klaim. Langsung dijalankan.", bullets:["Seberapa cepat kita menulis code?","Seberapa baik hasilnya saat dijalankan?","KMP menjawab keduanya sekaligus."], theme:"white"},
    {num:"03", label:"Shared Logic", title:"Share Yang Masuk Akal", body:"KMP tidak memaksa UI menjadi abstraksi. Anda share bagian yang memang layak di-share.", bullets:["Business logic & domain rules.","Networking & data layer.","Validation & state management.","UI? Tetap native, tetap platform-specific."], theme:"white"},
    {num:"04", label:"Nilai Bisnis Terbesar", title:"Incremental Migration", body:"Untuk perusahaan dengan investasi besar di native Android dan iOS, KMP tidak memaksa rewrite dari nol.", bullets:["Masuk per modul, bukan big-bang migration.","Mulai dari bagian yang paling memberikan value.","Tidak buang codebase lama.","Tidak ambil risiko migrasi sekaligus."], theme:"white"},
    {num:"05", label:"False Binary", title:"KMP Tidak Akan Membunuh Flutter", body:"Pertanyaannya bukan siapa yang menang. Pertanyaannya adalah: problem Anda apa?", bullets:["Flutter: cross-platform UI, satu codebase, mulai dari nol.","KMP: shared logic, native UI, leverage existing codebase.","Dua pendekatan berbeda untuk dua konteks berbeda."], theme:"white"},
    {num:"06", label:"Framework Selection", title:"Problem First, Framework Second", body:"Solusi terbaik kadang bukan mengganti semuanya — tapi membuat yang sudah ada menjadi lebih powerful.", bullets:["Codebase Anda sekarang seperti apa?","Berapa besar investasi yang sudah ada di native?","Framework mana yang memberi leverage terbesar?"], theme:"white"},
    {num:"07", label:"Terima kasih Iqbal Fauzi", title:"Closing", body:"Insight dan demo dari Iqbal Fauzi, Senior Mobile Developer di Bobobox. KMP sebagai opsi realistis, bukan sekadar teori.", bullets:["KotlinMultiplatform #KMP #Flutter.","#MobileDevelopment #SoftwareEngineering.","Evaluate based on your actual constraints."], theme:"white"},
  ],
};

